OLD_DECL="""var reduce=matchMedia('(prefers-reduced-motion: reduce)'), conn=navigator.connection||{}, cards=[], states=new WeakMap(), active=null, suspended=!!window.__mm45Suspended, disposed=false, scheduled=false, muted=true;
var conservative=!!(conn.saveData||/^(slow-)?2g$/.test(conn.effectiveType||''));
try{conservative=conservative||localStorage.getItem('mm46-data-saver')==='1';}catch(ignore){}"""
NEW_DECL="""var reduce=matchMedia('(prefers-reduced-motion: reduce)'), conn=navigator.connection||{}, cards=[], states=new WeakMap(), active=null, suspended=!!window.__mm45Suspended, disposed=false, scheduled=false, muted=true, memoryGb=Number(navigator.deviceMemory||4), networkType=String(conn.effectiveType||'').toLowerCase();
var conservative=!!conn.saveData;
try{var savedMode=localStorage.getItem('mm46-data-saver');if(savedMode==='1')conservative=true;else if(savedMode==='0')conservative=false;}catch(ignore){}
var fastNetwork=!conservative&&!/^(slow-)?2g$/.test(networkType),releaseDelay=1100;"""

OLD_SAVER="saverCopy.append(el('strong','','Hemat data'),el('small','','Putar setelah diketuk; tanpa memuat video berikutnya.'));"
NEW_SAVER="saverCopy.append(el('strong','','Hemat data'),el('small','','Putar setelah diketuk; buffer video berikutnya dibatasi.'));"

OLD_CHANGE="saver.addEventListener('change',function(){conservative=saver.checked;try{localStorage.setItem('mm46-data-saver',conservative?'1':'0');}catch(ignore){}budget();});"
NEW_CHANGE="saver.addEventListener('change',function(){conservative=saver.checked;fastNetwork=!conservative&&!/^(slow-)?2g$/.test(networkType);try{localStorage.setItem('mm46-data-saver',conservative?'1':'0');}catch(ignore){}budget();});"

OLD_BUFFER="""function attach(st,preload){if(!st)return;st.v.preload=preload;if(!st.v.hasAttribute('src')&&st.source){st.v.src=st.source;st.v.load();}st.v.dataset.mm46Attached='1';}
function release(st){if(!st)return;st.v.pause();clearTimeout(st.waitTimer);st.card.removeAttribute('data-mm46-loading');if(st.v.hasAttribute('src')){st.position=Number.isFinite(st.v.currentTime)?st.v.currentTime:0;st.v.removeAttribute('src');st.v.load();}delete st.v.dataset.mm46Attached;}
function pauseAll(){cards.forEach(function(c){var st=states.get(c);if(st&&!st.v.paused)st.v.pause();});}
function budget(){var i=cards.indexOf(active);cards.forEach(function(c,n){var st=states.get(c);if(!st)return;if(!isReels()||suspended||document.hidden){if(c===active)st.v.pause();else release(st);return;}if(n===i)attach(st,conservative?'none':'metadata');else if(!conservative&&!reduce.matches&&n===i+1)attach(st,'metadata');else release(st);});}
function start(st,user){if(!st||!mayPlay())return;if(!user&&(conservative||reduce.matches||st.userPaused))return;cards.forEach(function(c){var x=states.get(c);if(x&&x!==st)x.v.pause();});attach(st,'metadata');st.v.muted=muted;st.card.removeAttribute('data-mm46-error');st.v.play().then(function(){if(active!==st.card||!mayPlay())st.v.pause();else{st.userPaused=false;st.card.removeAttribute('data-mm46-blocked');}}).catch(function(){st.card.dataset.mm46Blocked='1';st.v.pause();});}"""
NEW_BUFFER="""function cancelRelease(st){if(st&&st.releaseTimer){clearTimeout(st.releaseTimer);st.releaseTimer=0;}}
function attach(st,preload,priority){if(!st)return;cancelRelease(st);st.v.preload=preload||'metadata';st.v.setAttribute('fetchpriority',priority||'low');if(!st.v.hasAttribute('src')&&st.source){st.v.src=st.source;st.v.load();}st.v.dataset.mm46Attached='1';}
function release(st){if(!st)return;cancelRelease(st);st.v.pause();clearTimeout(st.waitTimer);st.card.removeAttribute('data-mm46-loading');if(st.v.hasAttribute('src')){st.position=Number.isFinite(st.v.currentTime)?st.v.currentTime:0;st.v.removeAttribute('src');st.v.load();}delete st.v.dataset.mm46Attached;}
function scheduleRelease(st,delay){if(!st||st.releaseTimer)return;st.releaseTimer=setTimeout(function(){st.releaseTimer=0;release(st);},delay==null?releaseDelay:delay);}
function pauseAll(){cards.forEach(function(c){var st=states.get(c);if(st&&!st.v.paused)st.v.pause();});}
function budget(){var i=cards.indexOf(active),keepAhead=fastNetwork&&memoryGb>=4?2:1;cards.forEach(function(c,n){var st=states.get(c);if(!st)return;if(i<0){scheduleRelease(st,300);return;}if(!isReels()||suspended||document.hidden){if(c===active){st.v.pause();attach(st,'metadata','low');}else scheduleRelease(st,300);return;}var distance=n-i;if(distance===0)attach(st,'auto','high');else if(distance===1)attach(st,fastNetwork?'auto':'metadata',fastNetwork?'high':'low');else if(distance===-1)attach(st,'metadata','low');else if(distance>1&&distance<=keepAhead)attach(st,'metadata','low');else scheduleRelease(st,releaseDelay);});}
function start(st,user){if(!st||!mayPlay())return;if(!user&&(conservative||reduce.matches||st.userPaused))return;cards.forEach(function(c){var x=states.get(c);if(x&&x!==st)x.v.pause();});attach(st,'auto','high');st.v.muted=muted;st.card.removeAttribute('data-mm46-error');st.card.removeAttribute('data-mm433-slow');st.v.play().then(function(){if(active!==st.card||!mayPlay())st.v.pause();else{st.userPaused=false;st.card.removeAttribute('data-mm46-blocked');budget();}}).catch(function(){st.card.dataset.mm46Blocked='1';st.v.pause();});}"""

